        ? rawTracks
            .map((track) => (track && typeof track === 'object' ? (track as Record<string, unknown>).title : undefined))
            .filter((title): title is string => typeof title === 'string' && !!title.trim())
            .slice(0, 50)
        : [];
    return { fields, analysis, trackTitles };
}

