            userId
        );
        imageUrl = result.url;
        thumbnailUrl = result.thumbnailUrl;
        logger.debug(`[StorageService] Image saved (${result.strategy}):`, item.id);
    }
} catch (error: unknown) {
    logger.error('[StorageService] Cloud upload failed:', error);
